#!/usr/bin/env python3
"""Human-readable practice sheets for a curated subset of the 120 static sites.

Examples, comparisons and limitations are authored per topic. These are not
claims of performed fieldwork, professional qualification or live measurements.
The published HTML is inert and depends on no scripts or remote resources.
"""
from dataclasses import dataclass
from html import escape


@dataclass(frozen=True)
class Workbook:
    title: str
    introduction: str
    steps: tuple[str, str, str]
    comparisons: tuple[tuple[str, str], tuple[str, str], tuple[str, str]]
    limitations: str


WORKBOOKS = {}


def add(name, title, introduction, steps, comparisons, limitations):
    if name in WORKBOOKS:
        raise ValueError('duplicate workbook: ' + name)
    if len(steps) != 3 or len(comparisons) != 3:
        raise ValueError('invalid workbook layout: ' + name)
    item = Workbook(title, introduction, tuple(steps), tuple(tuple(row) for row in comparisons), limitations)
    if (len(title) < 8 or len(introduction) < 80 or len(limitations) < 70
            or any(len(text) < 70 for text in steps)
            or any(len(label) < 2 or len(detail) < 25 for label, detail in comparisons)):
        raise ValueError('workbook text too short: ' + name)
    WORKBOOKS[name] = item


