CATALOG_WORKBOOKS = frozenset(n for n in WORKBOOKS if 13 <= int(n.split('-', 1)[0]) <= 108)
CLASSIC_WORKBOOKS = frozenset(n for n in WORKBOOKS if 1 <= int(n.split('-', 1)[0]) <= 12)
SIGNATURE_WORKBOOKS = frozenset(n for n in WORKBOOKS if 109 <= int(n.split('-', 1)[0]) <= 120)
if (len(WORKBOOKS), len(CATALOG_WORKBOOKS), len(CLASSIC_WORKBOOKS), len(SIGNATURE_WORKBOOKS)) != (104, 80, 12, 12):
    raise RuntimeError('workbook edition should cover 80 catalog and all 24 separate sites')


def render(name, lang='ru'):
    """Accessible static content block, links independent of URL layout."""
    item = WORKBOOKS.get(name)
    if item is None:
        return ''
    ru = lang == 'ru'
    esc = lambda text: escape(text, quote=True)
    heading = 'Практикум' if ru else 'Field guide'
    procedure = 'Последовательность' if ru else 'Method'
    reference = 'Краткая памятка' if ru else 'Quick reference'
    th1, th2 = ('Признак', 'На что смотреть') if ru else ('Feature', 'What to check')
    note = 'Ограничения и безопасность' if ru else 'Limits and safety'
    steps = ''.join(f'<li>{esc(text)}</li>' for text in item.steps)
    table_rows = ''.join(f'<tr><th scope="row">{esc(left)}</th><td>{esc(right)}</td></tr>' for left, right in item.comparisons)
    return (f'<section class="workbook" id="practical-guide" aria-labelledby="practical-heading">'
            f'<p class="workbook-label">{heading}</p><h2 id="practical-heading">{esc(item.title)}</h2>'
            f'<p class="workbook-lead">{esc(item.introduction)}</p>'
            f'<h3>{procedure}</h3><ol class="workbook-steps">{steps}</ol>'
            f'<h3>{reference}</h3><div class="workbook-table-wrap"><table class="workbook-table">'
            f'<thead><tr><th scope="col">{th1}</th><th scope="col">{th2}</th></tr></thead>'
            f'<tbody>{table_rows}</tbody></table></div>'
            f'<div class="workbook-limits"><h3>{note}</h3><p>{esc(item.limitations)}</p></div>'
            f'</section>')


CSS = '''
.workbook{margin:clamp(28px,5vw,60px) 0;padding:clamp(22px,4vw,52px);background:var(--card, var(--soft, #f4f2ef));color:var(--ink, inherit);border:1px solid var(--line,var(--soft,#aaa));border-top:5px solid var(--highlight,var(--accent,#555));border-radius:9px;min-width:0}
.workbook-label{font-size:.78rem;font-weight:750;letter-spacing:.11em;text-transform:uppercase}
.workbook h2{font-size:clamp(1.8rem,3vw,3rem);line-height:1.18;margin:12px 0 20px;max-width:24ch}
.workbook .workbook-lead{font-size:1.06rem;line-height:1.8;max-width:75ch}
.workbook h3{font-size:1.2rem;margin:30px 0 15px;line-height:1.3}
.workbook-steps{padding-left:24px;margin:0;display:grid;gap:16px;max-width:85ch}
.workbook-steps li{padding-left:6px;line-height:1.8}
.workbook-table-wrap{overflow-x:auto;max-width:100%}
.workbook-table{border-collapse:collapse;width:100%;table-layout:fixed;font-size:.97rem;line-height:1.6}
.workbook-table th,.workbook-table td{padding:13px 17px;text-align:left;vertical-align:top;border-bottom:1px solid var(--line,var(--soft,#aaa));overflow-wrap:anywhere}
.workbook-table th:first-child{width:34%}
.workbook-table thead th{font-weight:800;border-bottom:2px solid var(--highlight,var(--accent,#555))}
.workbook-limits{border-left:4px solid var(--highlight,var(--accent,#555));padding:4px 20px;margin-top:24px;background:transparent}
.workbook-limits h3{margin:12px 0}
.workbook-limits p{line-height:1.75;max-width:75ch}
.workbook-jump{display:inline-block;margin:16px 0 0;font-weight:700;text-underline-offset:5px}
@media(max-width:600px){.workbook{padding:20px 16px;border-radius:0}.workbook-table th,.workbook-table td{padding:11px 9px}.workbook-table th:first-child{width:38%}}
@media print{.workbook{background:#fff!important;color:#111!important;border:1px solid #888!important;padding:15px!important;break-before:page;page-break-before:always}.workbook-steps li{break-inside:avoid}.workbook-table{color:#111!important}.workbook-limits{border-left:2px solid #333!important}}
'''.encode('utf-8')
